ALL = ["LY-211","LY-212","LY-215","LY-216","LY-217","LY-218","LY-219","LY-220","LY-221","LY-222","LY-227","LY-228","LY-230","LY-231","LY-232","LY-234","LY-235","LY-237","LY-240","LY-241","LY-242","LY-243","LY-244","LY-245","LY-246","LY-249","LY-250","LY-251","LY-252","LY-253","LY-254","LY-255","LY-259","LY-301","LY-304","LY-305","LY-306","LY-307","LY-309","LY-311"]
assert len(ALL) == 40 and set(ALL) == set(P.keys()), "id set mismatch"
written = 0
for cid in ALL:
    rec = P[cid]
    assert rec["case_id"] == cid
    assert isinstance(rec["prediction_text"], str) and rec["prediction_text"]
    assert isinstance(rec["basis"], str) and "tradition=liuyao" in rec["basis"]
    assert "第八节功量核" in rec["basis"] and "主线认定" in rec["basis"], cid
    assert 0.0 <= rec["confidence"] <= 1.0
    t = rec["trigger"]
    assert set(t.keys()) == {"changed_main","reserve_used","disputed","reason"}
    assert all(isinstance(t[k], bool) for k in ("changed_main","reserve_used","disputed"))
    with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
    written += 1
cm = sum(1 for c in ALL if P[c]["trigger"]["changed_main"])
ru = sum(1 for c in ALL if P[c]["trigger"]["reserve_used"])
di = sum(1 for c in ALL if P[c]["trigger"]["disputed"])
print(f"WROTE {written}/40 | trigger changed_main={cm} reserve_used={ru} disputed={di}")
